  "medium": "Tempera and gold on wood",
  "text": "St John, abbot of Sinai in the seventh century, wrote of the spiritual life as a ladder of thirty rungs, from renunciation of the world to love. Here monks climb it toward Christ, who reaches from heaven to receive them.\n\nSmall black demons pull at their habits with ropes and hooks, and some climbers fall headlong. On the left, monks pray for them. At the top of the ladder, St John himself is the first to arrive. The icon is still read aloud in a sense every Lent, when the fourth Sunday is kept in his memory.",
