  "medium": "Tempera on wood, 142 × 114 cm",
  "text": "Three angels visited Abraham at the oak of Mamre (Genesis 18). Rublev removes nearly everything else from the story and leaves the three seated around a table on which stands a single cup.\n\nThe angels are alike and yet distinct, and each inclines toward the others in a circle of attention. The church has long read them as an image of the Holy Trinity. The icon was painted in praise of St Sergius of Radonezh for the monastery he founded, and the Stoglav Council of 1551 named it the model for all icons of the Trinity. Rublev himself was glorified as a saint in 1988.",
