  "text": "Sent from Constantinople to Kiev around 1131, this icon passed to Vladimir and then, in 1395, to Moscow, where it was credited with turning back the army of Tamerlane. Its feast on 26 August recalls that meeting.\n\nIt is the classic image of tenderness. The Child presses his cheek to his mother's, his arm around her neck, while she looks out at us with sorrow, already knowing the Passion. Only the faces are original twelfth-century paint; the rest was renewed over the centuries. It is kept in the Church of St Nicholas in Tolmachi, part of the Tretyakov Gallery, where it remains an object of prayer.",
