  "medium": "Oil on panel, 53.5 × 44 cm",
  "text": "Seraphim (1754–1833) lived as a hermit in the forest near Sarov, praying for a thousand nights on a rock. In his last years he received pilgrims at his cell, greeting everyone with the paschal words: 'My joy, Christ is risen!'\n\nHe taught that the aim of the Christian life is the acquisition of the Holy Spirit. He was glorified in 1903 in the presence of the imperial family, and icons like this one spread quickly across Russia afterward.",
