  "medium": "Tempera on wood",
  "text": "The Zaraysk type shows Nicholas full-length and frontal, his arms raised, blessing with his right hand and holding the Gospel in his left. It is named after a wonderworking icon brought from Kherson to the town of Zaraysk in the thirteenth century.\n\nThe borders tell his life: his birth, his ordination, the gift of gold to three poor daughters, the rescue of sailors at sea, and the saving of three innocent men from execution.",
