  "home": {
   "name": "Cathedral of Holy Wisdom (St Sophia)",
   "lat": 58.5223,
   "lng": 31.2757,
   "city": "Veliky Novgorod"
  },
  "medium": "Tempera on wood",
  "text": "'Wisdom has built her house' (Proverbs 9). Novgorod gave this mysterious image to its cathedral. A fiery angel with red face and wings sits enthroned, crowned like an emperor. On either side stand the Mother of God and John the Forerunner, and above, Christ blesses from a medallion beneath the Etimasia, the throne prepared for the Last Judgment.\n\nHoly Wisdom is Christ himself, the Word through whom all things were made. Novgorod kept the cathedral's patronal feast on the Dormition, 15 August.",
  "image": "assets/icons/holy-wisdom-novgorod.jpg",
