  "originShort": "Russia",
  "home": {
   "name": "Walters Art Museum",
   "lat": 39.2965,
   "lng": -76.6156,
   "city": "Baltimore"
  },
  "medium": "Tempera on wood",
  "text": "Christ is crucified before the walls of Jerusalem. The painter adds a detail rarely shown: the dead rising from their tombs as tightly wrapped figures, after Matthew 27:52, 'the tombs also were opened, and many bodies of the saints which slept arose'.\n\nThe Russian cross has a slanted footrest. Tradition explains that it points up toward the penitent thief, who entered Paradise, and down toward the one who mocked.",
  "image": "assets/icons/walters-crucifixion-russian.jpg",
