  "home": {
   "name": "Timken Museum of Art",
   "lat": 32.7317,
   "lng": -117.1499,
   "city": "San Diego"
  },
  "medium": "Tempera on wood",
  "text": "In 320 forty soldiers of the Roman legion at Sebaste refused to sacrifice to the gods and were left to freeze on a frozen lake. A bathhouse stood warm on the shore for any who would recant. One did, and a guard who saw crowns descending on the others took his place.\n\nThe feast falls in Great Lent. This Novgorod panel, now in San Diego, shows them crowded together on the ice.",
  "image": "assets/icons/forty-martyrs-novgorod.jpg",
  "thumb": "assets/icons/forty-martyrs-novgorod-thumb.jpg",
  "w": 806,
  "h": 983,
