  "medium": "Tempera on wood",
  "text": "Three virgin-martyrs stand together. Barbara was shut in a tower by her pagan father and beheaded by him. Paraskeva, 'Friday', was the patron of Russian marketplaces, and Juliana of Nicomedia was martyred under Maximian.\n\nRussian icons often grouped holy women this way, as patrons of a family or a parish.",
