  "medium": "Tempera on wood, 314 × 106 cm",
  "text": "Gregory of Nazianzus (329–390) preached the five Theological Orations in Constantinople and defended the doctrine of the Trinity. The Church calls only three saints 'Theologian', and he is one.\n\nThis tall figure comes from the Deesis tier made in 1408 for the Dormition Cathedral in Vladimir, the tier associated with Andrei Rublev and Daniil Chorny.",
