  "medium": "Tempera on wood",
  "text": "Two soldier-martyrs share a name and often an icon. Theodore the Recruit (Tiron) burned a pagan temple at Amasea; Theodore Stratelates was a general at Heraclea.\n\nThe Recruit is remembered on the first Saturday of Lent for a miracle in 361, when he warned the Christians of Constantinople that the food in the markets had been defiled.",
  "image": "assets/icons/two-theodores-hermitage.jpg",
