  "medium": "Tempera on wood",
  "text": "A rare way of showing the Trinity: God the Father as an old man, the Son as a child on his knees, and the Holy Spirit as a dove within a medallion. Seraphim surround them, and saints stand at the sides, among them the stylites Symeon and Daniel on their pillars.\n\nThe Church was cautious about such images of the Father, which makes early examples like this one especially rare.",
